use std::boxed::Box;

pub fn new_node(item: i32) -> Box<Node> {
    Box::new(Node {
        key: item,
        left: None,
        right: None,
    })
}

pub fn inorder(root: &Option<Box<Node>>) {
    if let Some(node) = root {
        inorder(&node.left);
        print!("{} ", node.key);
        inorder(&node.right);
    }
}

pub fn min_value_node(node: &Option<Box<Node>>) -> Option<Box<Node>> {
    let mut current = node;
    while let Some(ref n) = current {
        current = &n.left;
    }
    current.clone()
}

pub fn insert(node: Option<Box<Node>>, key: i32) -> Option<Box<Node>> {
    if node.is_none() {
        return Some(new_node(key));
    }

    let mut node = node.unwrap();
    if key < node.key {
        node.left = insert(node.left, key);
    } else {
        node.right = insert(node.right, key);
    }
    Some(node)
}

pub fn delete_node(root: &mut Option<Box<Node>>, key: i32) -> Option<Box<Node>> {
    if root.is_none() {
        return root.take();
    }

    if let Some(ref mut node) = root {
        if key < node.key {
            node.left = delete_node(&mut node.left, key);
        } else if key > node.key {
            node.right = delete_node(&mut node.right, key);
        } else {
            if node.left.is_none() {
                return node.right.take();
            } else if node.right.is_none() {
                return node.left.take();
            }

            if let Some(mut temp) = min_value_node(&node.right) {
                node.key = temp.key;
                node.right = delete_node(&mut node.right, temp.key);
            }
        }
    }

    root.take()
}

pub fn main() {
    let mut root: Option<Box<Node>> = None;
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 70);
    root = insert(root, 60);
    root = insert(root, 80);
    println!("Inorder traversal of the given tree");
    inorder(&root);
    println!("\nDelete 20");
    root = delete_node(&mut root, 20);
    println!("Inorder traversal of the modified tree");
    inorder(&root);
    println!("\nDelete 30");
